1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  :root { --cell: 28px; }
9	  * { box-sizing: border-box; }
10	  body {
11	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
12	    background: #14161c; color: #e8e8ee; font: 15px/1.4 system-ui, sans-serif;
13	  }
14	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
15	  .board {
16	    display: grid; grid-template-columns: repeat(10, var(--cell)); grid-template-rows: repeat(20, var(--cell));
17	    gap: 1px; background: #2a2d36; border: 2px solid #3a3e4a;
18	  }
19	  .cell { width: var(--cell); height: var(--cell); background: #1c1f27; }
20	  .side { display: flex; flex-direction: column; gap: 14px; min-width: 130px; }
21	  .stat .label { font-size: 12px; text-transform: uppercase; letter-spacing: .08em; color: #8a8fa0; }
22	  .stat .value { font-size: 22px; font-weight: 600; }
23	  .preview { display: grid; grid-template-columns: repeat(4, 18px); grid-template-rows: repeat(2, 18px); gap: 1px; margin-bottom: 8px; }
24	  .preview .mini { width: 18px; height: 18px; background: transparent; }
25	  .help { font-size: 12px; color: #8a8fa0; }
26	  .game-over { font-size: 18px; font-weight: 700; color: #ff6b6b; }
27	  .cell.ghost { box-shadow: inset 0 0 0 2px rgba(232, 232, 238, .45); }
28	  .pause-btn { font: inherit; padding: 6px 10px; border-radius: 6px; border: 1px solid #3a3e4a; background: #22252e; color: inherit; cursor: pointer; }
29	  .paused { font-size: 18px; font-weight: 700; color: #f0d000; }
30	  .p-I { background: #00c8e0 !important; }
31	  .p-O { background: #f0d000 !important; }
32	  .p-T { background: #a040f0 !important; }
33	  .p-S { background: #30c050 !important; }
34	  .p-Z { background: #e03030 !important; }
35	  .p-J { background: #3060f0 !important; }
36	  .p-L { background: #f08c20 !important; }
37	</style>
38	</head>
39	<body>
40	<div class="game">
41	  <div class="board" data-testid="board" id="board"></div>
42	  <div class="side">
43	    <div class="stat"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
44	    <div class="stat"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
45	    <div class="stat"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
46	    <div class="stat"><div class="label">Next</div><div id="next" data-testid="next-piece"></div></div>
47	    <div class="stat"><div class="label">Hold</div><div id="hold" data-testid="hold-piece" data-piece=""></div></div>
48	    <button type="button" class="pause-btn" data-testid="pause-btn" id="pause-btn">Pause</button>
49	    <div class="paused" data-testid="paused-indicator" id="paused" hidden>Paused</div>
50	    <div class="game-over" data-testid="game-over" id="game-over" hidden>Game over</div>
51	    <div class="help">← → move<br>↑ or X rotate<br>↓ soft drop<br>Space hard drop<br>C or Shift hold<br>P pause</div>
52	  </div>
53	</div>
54	<script>
55	(function () {
56	  var ROWS = 20, COLS = 10, LETTERS = ["I", "O", "T", "S", "Z", "J", "L"];
57	
58	  // [REQ-001] spawn shapes as [row, col] on the board
59	  var SHAPES = {
60	    I: [[0, 3], [0, 4], [0, 5], [0, 6]],
61	    O: [[0, 4], [0, 5], [1, 4], [1, 5]],
62	    T: [[0, 4], [1, 3], [1, 4], [1, 5]],
63	    S: [[0, 4], [0, 5], [1, 3], [1, 4]],
64	    Z: [[0, 3], [0, 4], [1, 4], [1, 5]],
65	    J: [[0, 3], [1, 3], [1, 4], [1, 5]],
66	    L: [[0, 5], [1, 3], [1, 4], [1, 5]]
67	  };
68	
69	  // [REQ-002] rotation box per piece: size and spawn origin (top-left of the box on the board)
70	  var BOX = {
71	    I: { size: 4, origin: [-1, 3] },
72	    O: { size: 2, origin: [0, 4] },
73	    T: { size: 3, origin: [0, 3] }, S: { size: 3, origin: [0, 3] }, Z: { size: 3, origin: [0, 3] },
74	    J: { size: 3, origin: [0, 3] }, L: { size: 3, origin: [0, 3] }
75	  };
76	  var KICKS = [0, -1, 1, -2, 2];  // sideways shifts tried when a rotation does not fit
77	  var LOCK_TICKS = 2;             // [REQ-002] ticks unable to fall before a piece locks
78	  var MAX_LOCK_RESETS = 3;        // [REQ-002] lock delay restarts allowed per piece
79	  // [REQ-003] points per clear by rows at once, times level; clearing together always beats one at a time
80	  var CLEAR_POINTS = [0, 100, 300, 500, 800];
81	  var SOFT_DROP_POINTS = 1, HARD_DROP_POINTS = 2;  // [REQ-003] per cell moved down by the player
82	  var QUEUE_SIZE = 3;             // [REQ-004] upcoming pieces kept in the queue
83	  var PREVIEW_COUNT = 1;          // [REQ-006] upcoming pieces shown in the preview
84	  var LINES_PER_LEVEL = 10;       // [REQ-007] lines cleared for each level gained
85	
86	  var state = {
87	    board: [],      // board[row][col] = letter or null
88	    current: null,  // { type, cells: [[r,c],...], origin: [r,c], lockTicks, lockResets }
89	    upcoming: [],
90	    hold: null, holdUsed: false,  // [REQ-007] held letter; true once this piece has used its hold
91	    score: 0, level: 1, lines: 0,
92	    status: "running"
93	  };
94	  var timer = null;
95	  var tickStart = 0, pausedElapsed = 0;  // [REQ-009] when the current gravity interval began; time it had run at pause
96	
97	  var boardEl = document.getElementById("board");
98	  var cellEls = [];
99	  for (var r = 0; r < ROWS; r++) {
100	    cellEls.push([]);
101	    for (var c = 0; c < COLS; c++) {
102	      var el = document.createElement("div");
103	      el.className = "cell";
104	      el.setAttribute("data-testid", "cell");
105	      el.setAttribute("data-row", r);
106	      el.setAttribute("data-col", c);
107	      boardEl.appendChild(el);
108	      cellEls[r].push(el);
109	    }
110	  }
111	
112	  function emptyBoard() {
113	    var b = [];
114	    for (var r = 0; r < ROWS; r++) { b.push(new Array(COLS).fill(null)); }
115	    return b;
116	  }
117	
118	  function randomLetter() {
119	    return LETTERS[Math.floor(Math.random() * LETTERS.length)];
120	  }
121	
122	  function validLetters(queue) {
123	    return (Array.isArray(queue) ? queue : []).filter(function (l) { return SHAPES[l]; });
124	  }
125	
126	  // [REQ-004] keep enough upcoming pieces to fill the preview, padding with random ones
127	  function fillUpcoming() {
128	    while (state.upcoming.length < QUEUE_SIZE) state.upcoming.push(randomLetter());
129	  }
130	
131	  // [REQ-001] take the next piece from the queue, falling back to random
132	  function takeNext() {
133	    var letter = state.upcoming.length ? state.upcoming.shift() : randomLetter();
134	    fillUpcoming();
135	    return letter;
136	  }
137	
138	  // [REQ-004] [REQ-007] a new piece that does not fit where it spawns ends the game; type defaults to the next in queue
139	  function spawn(type) {
140	    type = type || takeNext();
141	    var cells = SHAPES[type].map(function (p) { return [p[0], p[1]]; });
142	    if (!fits(cells)) {
143	      state.current = null;
144	      state.status = "gameover";
145	      stopTimer();
146	      return;
147	    }
148	    state.current = {
149	      type: type,
150	      cells: cells,
151	      origin: BOX[type].origin.slice(),
152	      lockTicks: 0, lockResets: 0
153	    };
154	  }
155	
156	  function fits(cells) {
157	    return cells.every(function (p) {
158	      return p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS && !state.board[p[0]][p[1]];
159	    });
160	  }
161	
162	  function canMove(dr, dc) {
163	    return fits(state.current.cells.map(function (p) { return [p[0] + dr, p[1] + dc]; }));
164	  }
165	
166	  function tryMove(dr, dc) {
167	    if (!state.current || !canMove(dr, dc)) return false;
168	    var cur = state.current;
169	    cur.cells = cur.cells.map(function (p) { return [p[0] + dr, p[1] + dc]; });
170	    cur.origin = [cur.origin[0] + dr, cur.origin[1] + dc];
171	    if (dr > 0) cur.lockTicks = 0;
172	    return true;
173	  }
174	
175	  // [REQ-002] rotate clockwise inside the piece's box; try sideways shifts; refuse if nothing fits
176	  function tryRotateCW() {
177	    var cur = state.current, n = BOX[cur.type].size, o = cur.origin;
178	    var turned = cur.cells.map(function (p) {
179	      var lr = p[0] - o[0], lc = p[1] - o[1];
180	      return [o[0] + lc, o[1] + n - 1 - lr];
181	    });
182	    // a rotation near the top edge is pushed down just enough to stay on the board
183	    var dr = Math.max(0, -Math.min.apply(null, turned.map(function (p) { return p[0]; })));
184	    for (var i = 0; i < KICKS.length; i++) {
185	      var dc = KICKS[i];
186	      var cand = turned.map(function (p) { return [p[0] + dr, p[1] + dc]; });
187	      if (fits(cand)) {
188	        cur.cells = cand;
189	        cur.origin = [o[0] + dr, o[1] + dc];
190	        return true;
191	      }
192	    }
193	    return false;
194	  }
195	
196	  // [REQ-002] [REQ-005] restart the lock delay, at most MAX_LOCK_RESETS times per piece
197	  function restartLockDelay() {
198	    var cur = state.current;
199	    if (cur.lockResets < MAX_LOCK_RESETS) { cur.lockResets++; cur.lockTicks = 0; }
200	  }
201	
202	  // [REQ-002] sideways move; while resting it restarts the lock delay
203	  function shift(dc) {
204	    var resting = !canMove(1, 0);
205	    if (tryMove(0, dc) && resting) restartLockDelay();
206	  }
207	
208	  // [REQ-003] [REQ-005] soft drop scores per cell; on a resting piece it restarts the lock delay like a sideways move
209	  function softDrop() {
210	    if (tryMove(1, 0)) state.score += SOFT_DROP_POINTS;
211	    else restartLockDelay();
212	  }
213	
214	  // [REQ-003] remove full rows, drop everything above, count lines and score the clear
215	  function clearLines() {
216	    var kept = state.board.filter(function (row) { return !row.every(Boolean); });
217	    var cleared = ROWS - kept.length;
218	    if (!cleared) return;
219	    while (kept.length < ROWS) kept.unshift(new Array(COLS).fill(null));
220	    state.board = kept;
221	    state.score += CLEAR_POINTS[cleared] * state.level;
222	    // [REQ-007] one level per 10 lines crossed, counted on from the current level
223	    var gained = Math.floor((state.lines + cleared) / LINES_PER_LEVEL) - Math.floor(state.lines / LINES_PER_LEVEL);
224	    state.lines += cleared;
225	    if (gained > 0) { state.level += gained; startTimer(); }
226	  }
227	
228	  // [REQ-007] milliseconds between gravity steps at the current level
229	  function dropInterval() {
230	    return Math.max(100, 1000 - (state.level - 1) * 100);
231	  }
232	
233	  // [REQ-007] put the falling piece aside, or swap it with the held one; once per piece
234	  function holdPiece() {
235	    if (state.holdUsed) return;
236	    var held = state.hold;
237	    state.hold = state.current.type;
238	    state.holdUsed = true;
239	    spawn(held);
240	  }
241	
242	  // [REQ-001] [REQ-003] lock the falling piece, clear full rows and spawn the next one
243	  function lock() {
244	    var cur = state.current;
245	    cur.cells.forEach(function (p) {
246	      if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) state.board[p[0]][p[1]] = cur.type;
247	    });
248	    clearLines();
249	    state.holdUsed = false;
250	    spawn();
251	  }
252	
253	  // [REQ-001] [REQ-002] one gravity step: fall one row, or count one tick of lock delay
254	  function gravityStep() {
255	    if (state.status !== "running") return;
256	    if (!state.current) spawn();
257	    else if (!tryMove(1, 0) && ++state.current.lockTicks >= LOCK_TICKS) lock();
258	    render();
259	  }
260	
261	  // [REQ-009] cells where the falling piece would land, leaving out cells it already covers
262	  function ghostCells() {
263	    if (!state.current || state.status === "gameover") return [];
264	    var d = 0;
265	    while (canMove(d + 1, 0)) d++;
266	    var own = {};
267	    state.current.cells.forEach(function (p) { own[p[0] + "," + p[1]] = true; });
268	    return state.current.cells
269	      .map(function (p) { return [p[0] + d, p[1]]; })
270	      .filter(function (p) { return !own[p[0] + "," + p[1]]; });
271	  }
272	
273	  // [REQ-009] pause stops gravity; lock ticks and restarts are kept, and resume finishes the interrupted interval
274	  // so toggling pause can never hold off a gravity step or a lock
275	  function togglePause() {
276	    if (state.status === "running") {
277	      pausedElapsed = Date.now() - tickStart;
278	      stopTimer();
279	      state.status = "paused";
280	    } else if (state.status === "paused") {
281	      state.status = "running";
282	      stopTimer();
283	      timer = setTimeout(function () { gravityStep(); startTimer(); }, Math.max(0, dropInterval() - pausedElapsed));
284	    }
285	  }
286	
287	  // [REQ-001] [REQ-002] [REQ-003] [REQ-009] player actions; hard drop locks at once, with no delay; drops score per cell
288	  function input(action) {
289	    if (action === "pause") { togglePause(); render(); return; }
290	    if (state.status !== "running" || !state.current) return;
291	    if (action === "left") shift(-1);
292	    else if (action === "right") shift(1);
293	    else if (action === "rotateCW") tryRotateCW();
294	    else if (action === "softDrop") softDrop();
295	    else if (action === "hold") holdPiece();
296	    else if (action === "hardDrop") {
297	      while (tryMove(1, 0)) state.score += HARD_DROP_POINTS;
298	      lock();
299	    }
300	    render();
301	  }
302	
303	  // [REQ-001] synchronous render from the real game state
304	  function render() {
305	    var drawn = state.board.map(function (row) { return row.slice(); });
306	    if (state.current) {
307	      state.current.cells.forEach(function (p) {
308	        if (p[0] >= 0 && p[0] < ROWS && p[1] >= 0 && p[1] < COLS) drawn[p[0]][p[1]] = state.current.type;
309	      });
310	    }
311	    var ghost = {};  // [REQ-009]
312	    ghostCells().forEach(function (p) { ghost[p[0] + "," + p[1]] = true; });
313	    for (var r = 0; r < ROWS; r++) {
314	      for (var c = 0; c < COLS; c++) {
315	        var el = cellEls[r][c], letter = drawn[r][c], isGhost = !letter && ghost[r + "," + c] === true;
316	        el.className = letter ? "cell p-" + letter : isGhost ? "cell ghost" : "cell";
317	        el.setAttribute("data-ghost", isGhost ? "true" : "false");
318	        el.setAttribute("data-filled", letter ? "true" : "false");
319	        el.setAttribute("data-piece", letter || "");
320	      }
321	    }
322	    document.getElementById("score").textContent = String(state.score);
323	    document.getElementById("level").textContent = String(state.level);
324	    document.getElementById("lines").textContent = String(state.lines);
325	    renderNext();
326	    renderHold();
327	    document.getElementById("game-over").hidden = state.status !== "gameover";
328	    document.getElementById("paused").hidden = state.status !== "paused";
329	    var btn = document.getElementById("pause-btn");
330	    btn.textContent = state.status === "paused" ? "Resume" : "Pause";
331	    btn.disabled = state.status === "gameover";
332	  }
333	
334	  // [REQ-004] [REQ-006] only the next piece, coloured as on the board
335	  function renderNext() {
336	    var box = document.getElementById("next");
337	    box.innerHTML = "";
338	    state.upcoming.slice(0, PREVIEW_COUNT).forEach(function (type) {
339	      var grid = miniGrid(type);
340	      grid.setAttribute("data-testid", "next-piece-item");
341	      box.appendChild(grid);
342	    });
343	  }
344	
345	  // [REQ-007] the held piece, coloured as on the board
346	  function renderHold() {
347	    var box = document.getElementById("hold");
348	    box.innerHTML = "";
349	    box.setAttribute("data-piece", state.hold || "");
350	    if (state.hold) box.appendChild(miniGrid(state.hold));
351	  }
352	
353	  function miniGrid(type) {
354	    var grid = document.createElement("div");
355	    grid.className = "preview";
356	    grid.setAttribute("data-piece", type);
357	    var filled = {};
358	    SHAPES[type].forEach(function (p) { filled[p[0] + "," + (p[1] - 3)] = true; });
359	    for (var r = 0; r < 2; r++) {
360	      for (var c = 0; c < 4; c++) {
361	        var m = document.createElement("div");
362	        m.className = filled[r + "," + c] ? "mini p-" + type : "mini";
363	        grid.appendChild(m);
364	      }
365	    }
366	    return grid;
367	  }
368	
369	  function stopTimer() {
370	    if (timer) { clearInterval(timer); clearTimeout(timer); timer = null; }
371	  }
372	
373	  // [REQ-007] [REQ-009] gravity timer at the level's speed; stays stopped while paused or once the game is over
374	  function startTimer() {
375	    stopTimer();
376	    if (state.status !== "running") return;
377	    tickStart = Date.now();
378	    timer = setInterval(function () { tickStart = Date.now(); gravityStep(); }, dropInterval());
379	  }
380	
381	  // [REQ-001] start a fresh game, optionally with a fixed piece queue
382	  function newGame(queue) {
383	    state.board = emptyBoard();
384	    state.score = 0; state.level = 1; state.lines = 0;
385	    state.hold = null; state.holdUsed = false;
386	    state.status = "running";
387	    state.upcoming = validLetters(queue);
388	    state.current = null;
389	    spawn();
390	    startTimer();
391	    render();
392	  }
393	
394	  // [REQ-001] test control surface
395	  window.__tetris = {
396	    newGame: newGame,
397	    setQueue: function (queue) {
398	      state.upcoming = validLetters(queue);
399	      fillUpcoming();
400	      render();
401	    },
402	    setBoard: function (rows) {
403	      var b = emptyBoard();
404	      for (var r = 0; r < ROWS; r++) {
405	        var line = (rows && rows[r]) || "";
406	        for (var c = 0; c < COLS; c++) {
407	          var ch = line.charAt(c);
408	          b[r][c] = SHAPES[ch] ? ch : null;
409	        }
410	      }
411	      state.board = b;
412	      render();
413	    },
414	    // [REQ-007] set the level for testing; gravity speed follows
415	    setLevel: function (n) {
416	      state.level = Math.max(1, Math.floor(n) || 1);
417	      startTimer();
418	      render();
419	    },
420	    tick: function (n) {
421	      if (n === undefined) n = 1;
422	      for (var i = 0; i < n; i++) gravityStep();
423	    },
424	    input: input,
425	    getBoard: function () {
426	      return state.board.map(function (row) {
427	        return row.map(function (v) { return v || "."; }).join("");
428	      });
429	    },
430	    getState: function () {
431	      return {
432	        current: state.current
433	          ? {
434	              type: state.current.type,
435	              cells: state.current.cells.map(function (p) { return [p[0], p[1]]; }),
436	              lockTicks: state.current.lockTicks,
437	              lockResets: state.current.lockResets
438	            }
439	          : null,
440	        ghost: ghostCells(),  // [REQ-009]
441	        next: state.upcoming.slice(),
442	        hold: state.hold,
443	        dropInterval: dropInterval(),
444	        score: state.score, level: state.level, lines: state.lines,
445	        status: state.status
446	      };
447	    }
448	  };
449	
450	  document.addEventListener("keydown", function (e) {
451	    var map = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", x: "rotateCW", X: "rotateCW", " ": "hardDrop", Spacebar: "hardDrop", c: "hold", C: "hold", Shift: "hold", p: "pause", P: "pause" };
452	    var action = map[e.key];
453	    if (!action) return;
454	    e.preventDefault();
455	    input(action);
456	  });
457	
458	  // [REQ-009]
459	  document.getElementById("pause-btn").addEventListener("click", function (e) {
460	    e.currentTarget.blur();
461	    input("pause");
462	  });
463	
464	  newGame();
465	})();
466	</script>
467	</body>
468	</html>
