input.new_string:
// [REQ-010] keyboard controls; browser shortcuts (Ctrl/Cmd/Alt) pass through; holding P or R does not repeat
document.addEventListener("keydown", function (e) {
  if (e.ctrlKey || e.metaKey || e.altKey) return;
  var map = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", x: "rotateCW", X: "rotateCW", " ": "hardDrop", Spacebar: "hardDrop", c: "hold", C: "hold", Shift: "hold", p: "pause", P: "pause", r: "restart", R: "restart" };
  var action = map[e.key];
  if (!action) return;
  e.preventDefault();
  if (e.repeat && (action === "pause" || action === "restart")) return;
  input(action);
});

// [REQ-009]
document.getElementById("pause-btn").addEventListener("click", function (e) {
  e.currentTarget.blur();
  input("pause");
});

// [REQ-010] new game: empty board, score 0, lines 0, level 1, running
document.getElementById("restart-btn").addEventListener("click", function (e) {
  e.currentTarget.blur();
  input("restart");
});

